CONTACT={'email':'hello@kennystudio.cfd','phone':'+601167735644','display_phone':'+6011-6773 5644','whatsapp':'https://wa.me/message/DHXOYXRCJIKZK1','telegram':'https://t.me/KennyStudio'}
HOME_TITLE='Website Designer in Malaysia | Kenny Studio'
HOME_DESCRIPTION='Freelance website design in Malaysia: landing pages, business websites, e-commerce, Google Ads management and SEO. Discuss your project with Kenny Studio.'
SERVICES={
'website-design':{'title':'Website Design in Malaysia | Kenny Studio','description':'Freelance website design for Malaysian businesses and personal brands. Landing pages, business websites, e-commerce and custom systems with a clear project scope.','type':'Website Design','form':'business','number':'01','locales':{
'en':{'label':'Website Design','eyebrow':'DESIGN / BUILD / LAUNCH','h1':'A website that feels like your business.','intro':'Freelance website design in Malaysia for businesses, founders and personal brands. From a focused landing page to an e-commerce website or a custom system, Kenny Studio brings your content, visual identity and enquiry journey together.','scope':'What your website project can include','items':[
['Landing pages & business websites','Explain your offer clearly and guide visitors to an enquiry, booking or purchase. Build the page structure around the information your customers need.'],['Personal brands & portfolios','Bring your story, services and existing work together in a distinctive, easy-to-browse website.'],['E-commerce & bookings','Plan product pages, checkout, payment integrations and booking flows around the way your business operates.'],['CMS, dashboards & custom systems','Define content management, access roles, data flows and integrations before building the tools your team needs.'],['Responsive design & accessibility','Make navigation, forms and content usable across desktop, tablet and mobile, with keyboard access and reduced-motion support.'],['Search foundations & launch checks','Review titles, descriptions, internal links, image loading, sitemap and indexing settings as part of an agreed launch scope.']],
'note':'Website packages start from RM1,000 for the published scope. See Packages & Pricing for inclusions and add-ons. Final deliverables and quotation are confirmed before work begins; enquiry-budget choices are discussion estimates.','cta':'Discuss Your Website','outcome':'Clear content. A considered experience.','body':'We start with your audience, business goals and available content. You can review the direction and key pages before development, then test the website before launch. Dedicated ongoing SEO and Google Ads management can be scoped separately. Remote collaboration is available for international clients as well as businesses across Malaysia.','faq':[
['Can you work on an existing website?','Yes. Redesigns and improvements can be scoped after reviewing the current structure, platform, content and access. The right approach depends on what can be reused.'],['What determines the website quotation?','Page count, design complexity, content readiness, integrations, backend functionality and ongoing support affect the scope. Share your requirements for a tailored quote.'],['Does a website include ongoing SEO or advertising?','Search foundations can be included in the agreed build. Ongoing SEO and Google Ads management are separate services with their own scope. Advertising spend is separate from website or management fees.']]},
'zh':{'label':'网站设计','eyebrow':'设计 / 开发 / 上线','h1':'让网站，真正代表你的业务。','intro':'立足马来西亚，为企业、创始人与个人品牌提供独立网站设计。从落地页、企业网站到电商及定制系统，Kenny Studio 将内容、品牌视觉和咨询路径整合成完整体验。','scope':'网站项目可以包含','items':[['落地页与企业网站','清楚说明你的产品和服务，按客户需要的信息规划页面，引导咨询、预约或购买。'],['个人品牌与作品集','整理你的故事、专业能力、服务及真实作品，让访客更容易了解你。'],['电商与预约功能','按业务需要规划商品页、结账、支付整合和预约流程。'],['内容管理、后台与定制系统','先明确内容管理、权限、数据流程与整合需求，再开发团队需要的工具。'],['响应式设计与可访问性','兼顾电脑、平板、手机、键盘操作和减少动态效果设置，让浏览和表单易于使用。'],['搜索基础与上线检查','按约定范围检查标题、描述、内链、图片加载、网站地图与索引设置。']],'note':'网站套餐按公布范围从 RM1,000 起，包含内容与加购详见套餐与价格。开工前确认最终交付与报价；表单预算选项仅用于讨论。','cta':'咨询网站项目','outcome':'内容清晰，体验用心。','body':'先了解受众、业务目标与内容准备情况，再确认设计方向和关键页面。上线前提供预览与测试。持续 SEO 和 Google Ads 管理可另行确定服务范围，同时支持马来西亚及国际客户远程合作。','faq':[['可以改进现有网站吗？','可以。需先检查现有平台、结构、内容和访问权限，再决定哪些部分可以保留以及改进范围。'],['网站如何报价？','页面数量、设计复杂度、内容准备、整合功能、后台需求与维护范围都会影响报价。请提供需求以便评估。'],['网站包含长期 SEO 或广告吗？','按约定可包含搜索基础设置。长期 SEO 与 Google Ads 管理另行确定范围，广告支出也独立计算。']]},
'ms':{'label':'Reka Bentuk Laman Web','eyebrow':'REKA / BINA / LANCAR','h1':'Laman web yang mencerminkan perniagaan anda.','intro':'Reka bentuk laman web bebas di Malaysia untuk perniagaan, pengasas dan jenama peribadi. Daripada halaman pendaratan hingga e-dagang dan sistem tersuai, Kenny Studio menyatukan kandungan, identiti visual dan perjalanan pertanyaan pelanggan.','scope':'Skop projek laman web','items':[['Halaman pendaratan & laman perniagaan','Terangkan tawaran dengan jelas dan susun maklumat untuk pertanyaan, tempahan atau pembelian.'],['Jenama peribadi & portfolio','Gabungkan cerita, kepakaran, perkhidmatan dan hasil kerja sebenar dalam laman yang tersendiri.'],['E-dagang & tempahan','Rancang halaman produk, pembayaran, integrasi dan aliran tempahan mengikut operasi anda.'],['CMS, papan pemuka & sistem tersuai','Tetapkan pengurusan kandungan, peranan akses, aliran data dan integrasi sebelum pembangunan.'],['Reka responsif & kebolehcapaian','Pastikan navigasi, borang dan kandungan sesuai untuk komputer, tablet, telefon, papan kekunci dan tetapan kurang gerakan.'],['Asas carian & semakan pelancaran','Semak tajuk, penerangan, pautan dalaman, imej, peta laman dan tetapan pengindeksan mengikut skop.']],'note':'Pakej bermula RM1,000 mengikut skop diterbitkan. Lihat Pakej & Harga untuk kandungan serta tambahan. Skop akhir dipersetujui sebelum kerja; pilihan bajet borang ialah anggaran perbincangan.','cta':'Bincangkan Laman Web Anda','outcome':'Kandungan jelas. Pengalaman teliti.','body':'Kami bermula dengan khalayak, matlamat dan kandungan anda. Semak arah reka bentuk dan halaman utama sebelum pembangunan serta uji sebelum pelancaran. SEO berterusan dan pengurusan Google Ads boleh ditetapkan secara berasingan. Kerjasama jarak jauh tersedia untuk pelanggan Malaysia dan antarabangsa.','faq':[['Bolehkah laman sedia ada ditambah baik?','Ya. Platform, struktur, kandungan dan akses perlu disemak untuk menentukan bahagian yang boleh digunakan semula.'],['Apakah yang menentukan sebut harga?','Bilangan halaman, kerumitan reka bentuk, kandungan, integrasi, fungsi backend dan sokongan mempengaruhi skop. Kongsikan keperluan untuk sebut harga.'],['Adakah SEO dan iklan berterusan termasuk?','Asas carian boleh disertakan mengikut persetujuan. SEO berterusan dan pengurusan Google Ads mempunyai skop berasingan; belanja iklan juga berasingan.']]}}},
'google-ads-management':{'title':'Google Ads Management in Malaysia | Kenny Studio','description':'Google Ads setup and management for Malaysian businesses: keyword research, search campaigns, conversion tracking, optimisation and reporting. Request a tailored quote.','type':'Google Ads Management','form':'google-ads','number':'02','locales':{
'en':{'label':'Google Ads Management','eyebrow':'SEARCH / RELEVANCE / MEASUREMENT','h1':'Put your offer in front of people looking for it.','intro':'Google Ads management for small businesses in Malaysia and international campaigns where agreed. Build a focused search campaign around your services, the locations you serve and the actions you want visitors to take—not just clicks.','scope':'A clear campaign management scope','items':[['Search Advertising Campaign Setup','Structure search campaigns and ad groups around your services, priorities and agreed campaign goals.'],['Keyword Research & Negative Keywords','Research relevant searches and use negative keywords to reduce exposure to unsuitable enquiries and unrelated intent.'],['Advertising Copywriting','Write clear, relevant ad copy that reflects your offer and connects with the message on your landing page.'],['Location and Audience Targeting','Configure geographic and audience settings to suit the areas you actually serve and your campaign strategy.'],['Budget Planning & Monitoring','Agree a starting budget, monitor spending and review allocation against the available campaign data.'],['WhatsApp and Website Lead Conversion Tracking','Set up agreed tracking for website enquiries, WhatsApp clicks or form actions. A click is not automatically a qualified lead or a sale.'],['Campaign Optimisation','Review search terms, ads, targeting and landing-page alignment, then make adjustments based on the data available.'],['Monthly Performance Reporting','Explain spend, clicks and configured conversion actions, with context on what changed and what to review next.']],
'note':'Advertising spend is paid separately to Google. Kenny Studio charges a separate management fee, quoted after reviewing your needs. No fixed number of enquiries, sales or other results is promised.','cta':'Request a Google Ads Quote','outcome':'Make the journey after the click count.','body':'A relevant advertisement needs a useful destination. We can review your landing page, mobile experience and enquiry path alongside campaign setup. Tracking is scoped to the consent choices and account access available; platform figures and conversion counts have limitations. The next step is a conversation about your offer, locations, budget and current accounts.','faq':[['Is the Google advertising budget included?','No. Advertising spend is paid to Google separately. Kenny Studio’s management fee is quoted independently, based on the agreed setup and ongoing work.'],['Can you guarantee enquiries or sales?','No. Outcomes depend on demand, competition, budget, offer, landing pages and your follow-up process. We report the data available and make informed adjustments without guaranteeing results.'],['What access is needed to get started?','We first review the website and campaign goals. Approved access may then be needed to your Google Ads, analytics and tag-management accounts. Do not send passwords; use account invitations and the permissions agreed for the project.']]},
'zh':{'label':'Google Ads 广告管理','eyebrow':'搜索 / 相关性 / 衡量','h1':'让正在寻找服务的人，看见你的业务。','intro':'为马来西亚小型企业提供 Google Ads 搜索广告管理，也可按约定规划国际广告。围绕实际服务、地区和希望访客采取的行动建立广告，而不只关注点击。','scope':'清晰的广告管理范围','items':[['搜索广告建立','按服务内容、优先事项和目标规划广告系列与广告组。'],['关键词研究与否定关键词','研究相关搜索，使用否定关键词减少不适合的搜索意图和无关咨询。'],['广告文案撰写','用清晰、相关的文案说明你的服务，并与落地页内容保持一致。'],['地区与受众定位','按实际服务地区与广告策略设置地理位置及受众。'],['预算规划与监控','确认起始预算，监控支出，并根据可用数据评估分配。'],['WhatsApp 与网站咨询追踪','按约定设置表单、WhatsApp 点击等转化动作。点击并不自动等于有效咨询或成交。'],['广告优化','检查搜索词、广告、定位与落地页的一致性，再按数据调整。'],['每月表现报告','说明支出、点击和已设置的转化动作，并交代变化及后续检查重点。']],'note':'广告费用独立支付给 Google。Kenny Studio 另收管理费，评估需求后报价；不承诺固定咨询数量、销量或其他结果。','cta':'索取 Google Ads 报价','outcome':'让点击之后的体验也有方向。','body':'相关的广告需要合适的落地页。可同时检查手机体验、页面内容与咨询路径。追踪方案取决于同意设置和获批权限，平台统计也有其限制。先聊聊服务内容、地区、预算和现有账号。','faq':[['报价包含广告预算吗？','不包含。广告支出独立支付给 Google，管理费根据建立和持续管理范围另行报价。'],['可以保证咨询或成交吗？','不能。结果取决于需求、竞争、预算、服务、页面及跟进流程。以数据作调整，但不保证结果。'],['开始前需要什么权限？','先检查网站与目标，再按需要邀请访问广告、分析或标签管理账号。使用账号邀请与约定权限，不需要发送密码。']]},
'ms':{'label':'Pengurusan Google Ads','eyebrow':'CARIAN / KESESUAIAN / PENGUKURAN','h1':'Tampil apabila orang mencari tawaran anda.','intro':'Pengurusan Google Ads untuk perniagaan kecil di Malaysia, serta kempen antarabangsa mengikut persetujuan. Bina kempen carian berdasarkan perkhidmatan, lokasi dan tindakan pelanggan yang bermakna—bukan klik semata-mata.','scope':'Skop pengurusan kempen yang jelas','items':[['Persediaan Kempen Iklan Carian','Susun kempen dan kumpulan iklan berdasarkan perkhidmatan, keutamaan dan matlamat dipersetujui.'],['Kajian Kata Kunci & Kata Kunci Negatif','Kaji carian berkaitan dan kurangkan carian yang tidak sesuai melalui kata kunci negatif.'],['Penulisan Iklan','Tulis iklan yang jelas, relevan dan selaras dengan mesej halaman pendaratan.'],['Penyasaran Lokasi dan Khalayak','Tetapkan kawasan dan khalayak mengikut lokasi sebenar perkhidmatan serta strategi kempen.'],['Perancangan & Pemantauan Bajet','Persetujui bajet awal, pantau belanja dan semak agihan berdasarkan data yang tersedia.'],['Penjejakan WhatsApp dan Pertanyaan Web','Tetapkan tindakan seperti klik WhatsApp atau penghantaran borang. Klik tidak semestinya pertanyaan berkualiti atau jualan.'],['Pengoptimuman Kempen','Semak istilah carian, iklan, sasaran serta kesesuaian halaman dan buat pelarasan berdasarkan data.'],['Laporan Prestasi Bulanan','Terangkan belanja, klik dan tindakan penukaran yang ditetapkan, perubahan serta langkah seterusnya.']],'note':'Belanja iklan dibayar secara berasingan kepada Google. Kenny Studio mengenakan fi pengurusan berasingan selepas menilai keperluan. Bilangan pertanyaan atau jualan tertentu tidak dijamin.','cta':'Minta Sebut Harga Google Ads','outcome':'Pengalaman selepas klik juga penting.','body':'Iklan yang relevan memerlukan halaman yang berguna. Pengalaman mudah alih, kandungan dan aliran pertanyaan boleh disemak bersama kempen. Penjejakan bergantung pada persetujuan dan akses yang tersedia; angka platform mempunyai batasan. Mulakan dengan tawaran, lokasi, bajet dan akaun sedia ada.','faq':[['Adakah bajet iklan termasuk?','Tidak. Belanja iklan dibayar kepada Google. Fi pengurusan Kenny Studio disebut harga berasingan mengikut kerja persediaan dan pengurusan.'],['Bolehkah pertanyaan atau jualan dijamin?','Tidak. Hasil bergantung pada permintaan, persaingan, bajet, tawaran, halaman dan proses susulan. Pelarasan dibuat berdasarkan data tanpa jaminan hasil.'],['Apakah akses yang diperlukan?','Laman web dan matlamat disemak dahulu. Jemputan akses kepada akaun iklan, analitik atau pengurusan tag mungkin diperlukan. Gunakan jemputan akaun dan jangan hantar kata laluan.']]}}},
'seo':{'title':'SEO Services in Malaysia | Kenny Studio','description':'SEO audits, technical and on-page SEO, keyword research, Search Console, indexing checks and local SEO for Malaysian businesses. Request a tailored SEO quote.','type':'SEO Services','form':'seo','number':'03','locales':{
'en':{'label':'SEO Services','eyebrow':'AUDIT / IMPROVE / MONITOR','h1':'Build stronger foundations for organic discovery.','intro':'SEO services in Malaysia for businesses and personal brands that want clearer content and a technically sound website. Start with the issues that matter to your site, then work through an agreed improvement plan and review progress over time.','scope':'Practical SEO deliverables','items':[['SEO Website Audit','Review the current website, search setup, content and technical constraints to identify priorities.'],['Technical SEO','Address agreed crawlability, canonical, responsive rendering, accessibility and performance issues that affect the site’s foundations.'],['On-Page SEO','Improve page structure, headings and relevance around useful content and the questions your customers ask.'],['Keyword Research','Understand search intent and map relevant topics to appropriate pages without keyword stuffing.'],['Titles, Meta Descriptions and Content Optimisation','Write descriptive page titles and summaries, and refine content so each page has a clear purpose.'],['Google Search Console Setup','Help verify ownership through an approved method and configure access to the site’s actual search data.'],['Sitemap and Indexing Checks','Check XML sitemap entries, robots directives and indexability. Submission is not a guarantee that a page will be indexed.'],['Internal Linking','Connect related services and useful content with descriptive, crawlable links.'],['Local SEO / Google Business Profile Optimisation','Review eligible business-profile information separately from website SEO. Profile work depends on eligibility, ownership and the real business details supplied.'],['SEO Performance Reporting','Review available Search Console and analytics data, explain changes and recommend the next priorities.']],
'note':'Organic ranking improvements usually take time and are not guaranteed. Website SEO and Google Business Profile optimisation are distinct scopes; a profile does not replace a useful, technically sound website.','cta':'Request an SEO Quote','outcome':'Website SEO and local profile optimisation are different jobs.','body':'Website SEO improves your pages, content and technical setup. Google Business Profile work focuses on an eligible business listing, its accurate details and local presentation. We do not invent addresses or create profiles for ineligible businesses. Agree the scope that fits your actual business, then review progress using the data available.','faq':[['How soon will SEO improve rankings?','There is no fixed timeline or guaranteed position. Competition, existing content, technical constraints, authority and search-engine decisions all matter. We prioritise useful work and explain what the data does and does not show.'],['Is Google Business Profile included?','It can be scoped separately for an eligible business with verified ownership and accurate details. It is not the same as website SEO and is not automatically suitable for every remote or online-only business.'],['Do I need ongoing SEO?','An audit can identify a defined set of improvements. Ongoing work may be appropriate as content, competitors and your business change. The recommendation and quote depend on your starting point and goals.']]},
'zh':{'label':'SEO 搜索优化','eyebrow':'审查 / 改进 / 观察','h1':'为自然搜索，打好网站基础。','intro':'为马来西亚企业与个人品牌提供 SEO 服务，让内容更清楚、网站技术基础更完整。先确定实际问题，再按约定计划改善，并持续观察数据。','scope':'实用的 SEO 交付内容','items':[['网站 SEO 审查','检查网站、搜索设置、内容和技术限制，确定优先事项。'],['技术 SEO','处理约定的抓取、规范网址、响应式呈现、可访问性和性能问题。'],['页面 SEO','围绕客户需要的信息改善结构、标题层级和内容相关性。'],['关键词研究','了解搜索意图，将合适主题对应页面，避免堆砌关键词。'],['标题、描述与内容优化','为页面撰写准确的标题与摘要，确保各页有清晰目的。'],['Google Search Console 设置','按获批方式验证网站所有权，配置真实搜索数据的访问。'],['网站地图与索引检查','检查 XML 地图、robots 指令和可索引状态。提交不代表保证收录。'],['内部链接','用有意义、可抓取的链接连接相关服务和内容。'],['本地 SEO／商家资料优化','按真实业务、所有权与资格另行评估 Google 商家资料，不与网站 SEO 混为一谈。'],['SEO 表现报告','查看可用的搜索和分析数据，说明变化与后续重点。']],'note':'自然排名改善通常需要时间，不保证排名。网站 SEO 与 Google 商家资料优化是不同服务范围，商家资料不能取代内容实用、技术完整的网站。','cta':'索取 SEO 报价','outcome':'网站优化与本地商家资料，各有重点。','body':'网站 SEO 改善页面、内容和技术设置；Google 商家资料优化关注符合资格的商家列表和准确信息。不虚构地址，也不为不符合资格的业务建立资料。先按实际业务确定范围，再用可用数据观察进度。','faq':[['多久可以提高排名？','没有固定时间或保证位置。竞争、内容、技术、权威性和搜索引擎决定都会影响结果。我们按优先级改善并解释数据。'],['包含 Google 商家资料吗？','符合资格、拥有获批访问及真实信息的业务可另行确定范围。这与网站 SEO 不同，也并非适用于每一种纯线上业务。'],['需要持续 SEO 吗？','审查可先确定一批具体改善；内容、竞争和业务变化后，可能需要持续工作，建议和报价依起点与目标而定。']]},
'ms':{'label':'Perkhidmatan SEO','eyebrow':'AUDIT / TAMBAH BAIK / PANTAU','h1':'Bina asas carian organik yang lebih kukuh.','intro':'Perkhidmatan SEO di Malaysia untuk perniagaan dan jenama peribadi yang mahukan kandungan jelas serta laman web yang kukuh secara teknikal. Kenal pasti keutamaan, laksanakan pelan dipersetujui dan semak kemajuan dari semasa ke semasa.','scope':'Hasil kerja SEO yang praktikal','items':[['Audit SEO Laman Web','Semak laman, tetapan carian, kandungan dan batasan teknikal untuk menentukan keutamaan.'],['SEO Teknikal','Baiki isu kebolehrayapan, URL kanonik, paparan responsif, kebolehcapaian dan prestasi yang dipersetujui.'],['SEO Pada Halaman','Perkemas struktur, tajuk dan kesesuaian kandungan berdasarkan soalan pelanggan.'],['Kajian Kata Kunci','Fahami niat carian dan padankan topik dengan halaman tanpa pengulangan kata kunci berlebihan.'],['Pengoptimuman Tajuk, Meta dan Kandungan','Tulis tajuk serta ringkasan yang tepat dan jelaskan tujuan setiap halaman.'],['Persediaan Google Search Console','Bantu sahkan pemilikan melalui kaedah diluluskan dan akses data carian sebenar.'],['Semakan Peta Laman dan Pengindeksan','Semak peta XML, arahan robots dan kebolehindeksan. Penyerahan tidak menjamin pengindeksan.'],['Pautan Dalaman','Hubungkan perkhidmatan dan kandungan berkaitan melalui pautan yang jelas serta boleh dirayapi.'],['SEO Tempatan / Google Business Profile','Semak profil berasingan berdasarkan kelayakan, pemilikan dan maklumat perniagaan sebenar.'],['Laporan Prestasi SEO','Semak data carian dan analitik yang tersedia, terangkan perubahan serta keutamaan seterusnya.']],'note':'Penambahbaikan kedudukan organik lazimnya mengambil masa dan tidak dijamin. SEO laman web dan pengoptimuman Google Business Profile ialah skop berbeza.','cta':'Minta Sebut Harga SEO','outcome':'SEO laman web dan profil tempatan mempunyai skop berbeza.','body':'SEO laman web menambah baik halaman, kandungan dan tetapan teknikal. Google Business Profile memfokus pada penyenaraian perniagaan yang layak dan maklumat tepat. Alamat tidak direka dan profil tidak dibuat untuk perniagaan tidak layak. Tetapkan skop berdasarkan perniagaan sebenar dan pantau data tersedia.','faq':[['Bilakah kedudukan carian bertambah baik?','Tiada tempoh atau kedudukan yang dijamin. Persaingan, kandungan, teknikal, autoriti dan keputusan enjin carian mempengaruhi hasil. Keutamaan dan batasan data akan diterangkan.'],['Adakah Google Business Profile termasuk?','Ia boleh ditetapkan berasingan untuk perniagaan layak dengan pemilikan dan maklumat tepat. Ia berbeza daripada SEO laman web dan bukan untuk setiap perniagaan dalam talian sahaja.'],['Adakah SEO berterusan diperlukan?','Audit boleh mengenal pasti penambahbaikan tertentu. Kerja berterusan mungkin sesuai apabila kandungan, pesaing dan perniagaan berubah; cadangan bergantung pada matlamat dan keadaan semasa.']]}}}}
